\set ON_ERROR_STOP on
begin;
create function pg_temp.check(p_label text,p_ok boolean) returns void language plpgsql as $$
begin if p_ok is distinct from true then raise exception 'FAIL %',p_label; end if; raise notice 'ok %',p_label; end $$;
select pg_temp.check('Endpoint catalogue exists',to_regclass('public.webhook_endpoints') is not null);
select pg_temp.check('Four focused durable tables',to_regclass('public.webhook_endpoint_commands') is not null and to_regclass('public.webhook_deliveries') is not null and to_regclass('public.webhook_delivery_attempts') is not null);
select pg_temp.check('Browser cannot read envelopes',not has_table_privilege('authenticated','public.webhook_endpoints','SELECT'));
select pg_temp.check('Claims service-only',not has_function_privilege('authenticated','public.m1103_claim_webhook_delivery(uuid,text,integer)','EXECUTE'));
select pg_temp.check('Non-forced RLS',(select relrowsecurity and not relforcerowsecurity from pg_class where oid='public.webhook_endpoints'::regclass));
select pg_temp.check('Every webhook helper denies browser execute',not exists(select 1 from pg_proc where proname like 'm1103_%' and (has_function_privilege('anon',oid,'execute') or has_function_privilege('authenticated',oid,'execute'))));
select pg_temp.check('Service role cannot bypass atomic writes',not has_table_privilege('service_role','public.webhook_deliveries','UPDATE') and not has_table_privilege('service_role','public.webhook_endpoints','INSERT'));
select pg_temp.check('Pinned search paths',not exists(select 1 from pg_proc where proname like 'm1103_%' and not ('search_path=public, pg_temp'=any(proconfig))));
select pg_temp.check('Public metadata credential canary guard',public.m1103_metadata_contains_credential('Copied '||encode(decode(repeat('11',32),'hex'),'base64')) and public.m1103_metadata_contains_credential(replace(encode(decode(repeat('11',32),'hex'),'base64'),'=','%253D')) and not public.m1103_metadata_contains_credential('Receiver unreachable; operator reviewed.'));
select pg_temp.check('SQL accepts canonical percent-encoded and tilde paths',public.m1103_valid_webhook_url('https://receiver.example/hooks%20v1/~events'));
select pg_temp.check('SQL query and fragment remain rejected',not public.m1103_valid_webhook_url('https://receiver.example/hook?token=secret') and not public.m1103_valid_webhook_url('https://receiver.example/hook#fragment'));
select pg_temp.check('SQL blocks private/ambiguous literal destinations',not exists(select 1 from unnest(array['https://169.254.169.254/path','https://127.1','https://2130706433','https://0177.0.0.1','https://0x7f.0.0.1','https://metadata.google.internal']) x where public.m1103_valid_webhook_url(x)));
select pg_temp.check('Base uniqueness permits child replay',exists(select 1 from pg_indexes where tablename='webhook_deliveries' and indexname='webhook_deliveries_base_event_key' and indexdef like '%WHERE%'));
do $$
declare o uuid:=gen_random_uuid();u uuid:=gen_random_uuid();le uuid:=gen_random_uuid();p uuid:=gen_random_uuid();r uuid:=gen_random_uuid();f uuid:=gen_random_uuid();a uuid:=gen_random_uuid();ob uuid:=gen_random_uuid();ep uuid:=gen_random_uuid();kid uuid:=gen_random_uuid();epoch bigint;v record;c record;z record;dd uuid;dg integer;key uuid:=gen_random_uuid();ev text;source uuid;cn uuid;run uuid;v_digest text;oldversion integer;cnt integer;secret jsonb;anchor uuid:=gen_random_uuid();freshkid uuid;prevslot jsonb;newenv jsonb;before_version integer;fresh_source uuid;body text;child uuid;grandchild uuid;parentversion integer;urlpreview record;signer record;signer_id uuid;signer_gen integer;signer_body text;ep2 uuid:=gen_random_uuid();
begin
 insert into public.users(id,email) values(u,'m1103-'||u::text||'@cra.test');
