 insert into public.products(id,organization_id,legal_entity_id,legal_entity_version,legal_entity_snapshot,name,internal_code,product_type,responsible_owner_id,created_by,updated_by) values(p,o,le,0,'{}','Fixture','M1103','standalone_software',u,u,u);
 insert into public.product_releases(id,organization_id,product_id,legal_entity_id,legal_entity_version,legal_entity_snapshot,label,release_version,created_by,updated_by) values(r,o,p,le,0,'{}','Fixture','1',u,u);
 secret:=jsonb_build_object('keyId',kid,'secretId',kid,'revision',1,'envelope',jsonb_build_object('format','aes-256-gcm-v1','keyId','test-master','ciphertext',encode('cipher'::bytea,'base64'),'nonce',encode(decode(repeat('11',12),'hex'),'base64'),'authTag',encode(decode(repeat('11',16),'hex'),'base64')));
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'create',null,key,repeat('a',64),'test-master',epoch,jsonb_build_object('displayName','Fixture','url','https://receiver.example.test/events','eventTypes',array['product.release.market_availability_changed','product.release.lifecycle_changed','product.release.placed_on_market_changed','product.relationship.graph_changed','vulnerability.assessment.submitted','vulnerability.assessment.approved','vulnerability.assessment.rejected','vulnerability.assessment.superseded','vulnerability.remediation_anchor.recorded','vulnerability.remediation_anchor.corrected','reporting.deadline.threshold_crossed','reporting.deadline.breached','reporting.filing.recorded','connector.sync_completed','connector.sync_failed'],'productIds',array[p],'secret',secret));
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,gen_random_uuid(),u,'create',null,gen_random_uuid(),repeat('f',64),'test-master',epoch,jsonb_build_object('displayName','Foreign scope','url','https://receiver.example.test/events','eventTypes',array['connector.sync_failed'],'productIds',array[gen_random_uuid()]));
 perform pg_temp.check('Foreign product configuration rejected without effects',v.outcome='invalid_request' and (select count(*)=1 from public.webhook_endpoints where organization_id=o));
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'create',null,key,repeat('a',64),'test-master',epoch,'{}');
 perform pg_temp.check('Create durable command and disabled endpoint',v.outcome in ('created','replayed') and not (v.endpoint->>'enabled')::boolean and (select count(*)=1 from public.webhook_endpoint_commands where organization_id=o));
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,gen_random_uuid(),u,'create',null,key,repeat('a',64),'test-master',epoch,'{}');
 perform pg_temp.check('Create retry stable endpoint identity',v.outcome='replayed' and (v.endpoint->>'id')::uuid=ep);
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'create',null,key,repeat('b',64),'test-master',epoch,'{}');
 perform pg_temp.check('Changed idempotency payload conflicts',v.outcome='idempotency_conflict');
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'enable',1,gen_random_uuid(),repeat('b',64),'test-master',epoch,'{}');
 perform pg_temp.check('Enable increments optimistic version',v.outcome='updated' and (v.endpoint->>'version')::integer=2);
 for ev in select unnest(array['release.market_availability_changed','release.lifecycle_changed','release.placed_on_market_changed','product_relationship.graph_changed']) loop
  source:=gen_random_uuid();insert into public.product_regulatory_outbox_events(id,organization_id,product_id,release_id,event_type,event_key,payload,correlation_id,occurred_at) values(source,o,p,r,ev,source::text,'{"secret_canary":"never_send"}',gen_random_uuid(),clock_timestamp());
 end loop;
 perform pg_temp.check('Four actual product source inserts captured atomically',(select count(*)=4 from public.webhook_deliveries where organization_id=o));
 perform pg_temp.check('Raw source canary absent',(select not bool_or(coalesce(payload_bytes,'') like '%never_send%') from public.webhook_deliveries where organization_id=o));
 insert into public.vulnerability_findings select (jsonb_populate_record(null::public.vulnerability_findings,to_jsonb(x)||jsonb_build_object('id',f,'organization_id',o,'release_id',r,'component_identity','m1103-'||f::text))).* from public.vulnerability_findings x limit 1;
 insert into public.vulnerability_finding_assessments(id,organization_id,finding_id,revision,vex_status,detail,approval_state,approval_required,policy_severity,policy_version,submitted_by,updated_by) values(a,o,f,1,'affected','Fixture','approval_not_required',false,'unknown',0,u,u);
 for ev in select unnest(array['submitted','approved','rejected','superseded']) loop
  insert into public.vulnerability_finding_assessment_history_events(organization_id,assessment_id,event_type,actor_user_id,new_values) values(o,a,ev,u,'{}');
 end loop;
 insert into public.vulnerability_finding_remediation_anchors(id,organization_id,finding_id,revision,remediation_kind,mitigation_description,recorded_by) values(anchor,o,f,1,'mitigation','Fixture',u);
 for ev in select unnest(array['remediation_anchor.recorded','remediation_anchor.corrected']) loop
  source:=gen_random_uuid();insert into public.product_regulatory_outbox_events(id,organization_id,product_id,release_id,finding_id,remediation_anchor_id,event_type,event_key,payload,correlation_id,occurred_at) values(source,o,p,r,f,anchor,ev,source::text,'{}',gen_random_uuid(),clock_timestamp());
 end loop;
 insert into public.reporting_obligations(id,organization_id,obligation_type,source_finding_id,awareness_at,awareness_basis,rule_set_id,rule_set_version,rule_snapshot,created_by_user_id,created_by_display_name) values(ob,o,'actively_exploited_vulnerability',f,date_trunc('second',clock_timestamp()),'Fixture',(select id from public.reporting_rule_sets limit 1),1,'{}',u,'Fixture');
 for ev in select unnest(array['deadline_threshold_crossed','deadline_breached','filing_recorded']) loop
  insert into public.reporting_obligation_events(organization_id,obligation_id,event_kind) values(o,ob,ev);
 end loop;
 select * into v from public.m11_create_connector_atomic(o,u,epoch,gen_random_uuid(),'reference_conformance','M1103','1.0.0','v1','{}','manual');cn:=(v.connector->>'id')::uuid;
 for ev in select unnest(array['completed','failed']) loop
  select * into v from public.m11_begin_sync_run_atomic(o,cn,u,epoch,'incremental',gen_random_uuid(),gen_random_uuid());run:=(v.run->>'id')::uuid;
  insert into public.sync_run_plan_items(organization_id,sync_run_id,external_id,entity_type,proposed_action,field_diffs,issues,cra_product_id) values(o,run,'fixture','product','unchanged','{}','[]',p);
  update public.sync_runs set status='running',started_at=clock_timestamp() where organization_id=o and id=run;
  update public.sync_runs set status=ev,finished_at=clock_timestamp(),committed_at=case when ev='completed' then clock_timestamp() end where organization_id=o and id=run;
 end loop;
 perform pg_temp.check('All fifteen backed source events captured',(select count(distinct event_type)=15 from public.webhook_deliveries where organization_id=o));
 select * into c from public.m1103_claim_webhook_delivery(o,'worker-a',60);dd:=(c.result#>>'{delivery,id}')::uuid;dg:=(c.result->>'leaseGeneration')::integer;
