 select * into v from public.m1103_complete_webhook_delivery(o,dd,'worker-a',0,204,1,0);
 perform pg_temp.check('Late generation cannot finish',v.outcome='lease_lost');
 body:=jsonb_build_object('schemaVersion',1,'eventId',c.result#>>'{delivery,eventId}','deliveryId',c.result#>>'{delivery,deliveryId}','eventType',c.result#>>'{delivery,eventType}','occurredAt',c.result#>>'{delivery,occurredAt}','organizationId',o,'resource',c.result#>'{delivery,resource}')::text;
 select * into v from public.m1103_prepare_webhook_delivery(o,dd,'worker-a',dg,u,epoch,body,1);
