 perform pg_temp.check('Retry After obeyed and provider code discarded',v.outcome='retrying' and (select next_attempt_at>=clock_timestamp()+interval '119 seconds' and last_failure_code='receiver_rate_limited' from public.webhook_deliveries where id=dd));
 begin update public.webhook_delivery_attempts set worker_id='tampered' where organization_id=o and delivery_row_id=dd;raise exception 'attempt unexpectedly changed';exception when object_not_in_prerequisite_state then null;end;
 perform pg_temp.check('Closed attempt immutable',true);
 update public.webhook_deliveries set next_attempt_at=clock_timestamp()-interval '1 second' where id=dd;
 select * into c from public.m1103_claim_webhook_delivery(o,'worker-b',60);
 -- Another pending source might precede dd; use its claim to exercise restart.
 dd:=(c.result#>>'{delivery,id}')::uuid;dg:=(c.result->>'leaseGeneration')::integer;
