 select * into c from public.m1103_claim_webhook_delivery(o,'worker-c',60);
 perform pg_temp.check('Expired lease rescheduled with jitter',(select status='retrying' and lease_owner is null and next_attempt_at>clock_timestamp() from public.webhook_deliveries where id=dd));
