 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'replay',2,gen_random_uuid(),repeat('c',64),'test-master',epoch,jsonb_build_object('deliveryId',dd,'expectedDeliveryVersion',oldversion,'previewDigest',z.preview->>'previewDigest'),'Reviewed receiver recovery');
 perform pg_temp.check('Replay child preserves event parent',(v.command->>'deliveryId')::uuid<>dd and exists(select 1 from public.webhook_deliveries n join public.webhook_deliveries parent on parent.id=n.parent_delivery_id where n.parent_delivery_id=dd and n.event_id=parent.event_id and parent.status='failed'));
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'replay',2,gen_random_uuid(),repeat('f',64),'test-master',epoch,jsonb_build_object('deliveryId',dd,'expectedDeliveryVersion',oldversion,'previewDigest',z.preview->>'previewDigest'),'Duplicate reviewed recovery');
 perform pg_temp.check('Duplicate active replay rejected',v.outcome='conflict');
