 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'replay',2,gen_random_uuid(),repeat('f',64),'test-master',epoch,jsonb_build_object('deliveryId',child,'expectedDeliveryVersion',1,'previewDigest',urlpreview.preview->>'previewDigest'),'Reviewed child recovery');
 grandchild:=(v.command->>'deliveryId')::uuid;
 perform pg_temp.check('Grandchild reviewed replay created',grandchild is not null);
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'replay',2,gen_random_uuid(),repeat('f',64),'test-master',epoch,jsonb_build_object('deliveryId',dd,'expectedDeliveryVersion',oldversion,'previewDigest',z.preview->>'previewDigest'),'Competing ancestor recovery');
 perform pg_temp.check('Active replay uniqueness spans entire event lineage',v.outcome='conflict');

