 freshkid:=gen_random_uuid();secret:=jsonb_set(jsonb_set(jsonb_set(secret,'{keyId}',to_jsonb(freshkid)),'{secretId}',to_jsonb(freshkid)),'{revision}','3');
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'rotate_secret',3,gen_random_uuid(),repeat('a',64),'test-master',epoch,jsonb_build_object('secret',secret,'overlapSeconds',3600));
