 -- A second connector source with no known product scope must be withheld.
 select * into v from public.m11_create_connector_atomic(o,u,epoch,gen_random_uuid(),'reference_conformance','M1103 unknown','1.0.0','v1','{}','manual');cn:=(v.connector->>'id')::uuid;
