 perform pg_temp.check('URL replacement atomically cancels old receiver work',v.outcome='updated' and (select destination_revision=2 from public.webhook_endpoints where id=ep) and not exists(select 1 from public.webhook_deliveries where organization_id=o and status in ('pending','retrying','delivering')));
