 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'replay',4,gen_random_uuid(),repeat('e',64),'test-master',epoch,jsonb_build_object('deliveryId',dd,'expectedDeliveryVersion',oldversion,'previewDigest',urlpreview.preview->>'previewDigest'),'Review new receiver');
 perform pg_temp.check('Changed receiver replay blocked without explicit confirmation',v.outcome='conflict');
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'replay',4,gen_random_uuid(),repeat('e',64),'test-master',epoch,jsonb_build_object('deliveryId',dd,'expectedDeliveryVersion',oldversion,'previewDigest',urlpreview.preview->>'previewDigest','confirmDestinationChange',true),'Review new receiver');
 perform pg_temp.check('Confirmed replay has fresh projection, no historical body copy',v.outcome='updated' and (select endpoint_url='https://changed-receiver.example.test/events' and payload_bytes is null from public.webhook_deliveries where id=(v.command->>'deliveryId')::uuid));
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'disable',4,gen_random_uuid(),repeat('d',64),'test-master',epoch,'{}','Pause receiver');
 perform pg_temp.check('Disable cancels all pending and leased work',v.outcome='updated' and not exists(select 1 from public.webhook_deliveries where organization_id=o and status in ('pending','retrying','delivering')));
