 perform pg_temp.check('Export redacts key slots',not public.m1_export_business_record_jsonb('webhook_endpoints','{"secret_ciphertext":"CANARY","display_name":"safe"}')?'secret_ciphertext');
 -- A no-overlap rotation must never authorize a previously claimed old key.
 kid:=gen_random_uuid();secret:=jsonb_set(jsonb_set(jsonb_set(secret,'{keyId}',to_jsonb(kid)),'{secretId}',to_jsonb(kid)),'{revision}','1');
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep2,u,'create',null,gen_random_uuid(),repeat('e',64),'test-master',epoch,jsonb_build_object('displayName','Zero overlap','url','https://receiver.example.test/events','eventTypes',array['connector.sync_completed'],'productIds',array[p],'secret',secret));
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep2,u,'test',1,gen_random_uuid(),repeat('e',64),'test-master',epoch,'{}');
 select * into signer from public.m1103_claim_webhook_delivery(o,'zero-overlap',60);signer_id:=(signer.result#>>'{delivery,id}')::uuid;signer_gen:=(signer.result->>'leaseGeneration')::integer;
 signer_body:=jsonb_build_object('schemaVersion',1,'eventId',signer.result#>>'{delivery,eventId}','deliveryId',signer.result#>>'{delivery,deliveryId}','eventType',signer.result#>>'{delivery,eventType}','occurredAt',signer.result#>>'{delivery,occurredAt}','organizationId',o,'resource',signer.result#>'{delivery,resource}')::text;
 freshkid:=gen_random_uuid();secret:=jsonb_set(jsonb_set(jsonb_set(secret,'{keyId}',to_jsonb(freshkid)),'{secretId}',to_jsonb(freshkid)),'{revision}','2');
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep2,u,'rotate_secret',1,gen_random_uuid(),repeat('e',64),'test-master',epoch,jsonb_build_object('secret',secret,'overlapSeconds',0));
 select * into v from public.m1103_prepare_webhook_delivery(o,signer_id,'zero-overlap',signer_gen,u,epoch,signer_body,1);
 perform pg_temp.check('Zero overlap rejects old claimed signer',v.outcome='forbidden');
 update public.webhook_deliveries set lease_expires_at=clock_timestamp()-interval '1 second',deadline_at=clock_timestamp()-interval '1 second' where id=signer_id;
 select * into v from public.m1103_claim_webhook_delivery(o,'expired-deadline',60);
 perform pg_temp.check('Elapsed deadline closes abandoned attempt without fresh claim',(select status='failed' and lease_owner is null and lease_generation=signer_gen from public.webhook_deliveries where id=signer_id));
 update public.organization_permissions_version set version=version+1 where organization_id=o;
 select * into v from public.m1103_execute_webhook_endpoint_command_atomic(o,ep,u,'create',null,key,repeat('a',64),'test-master',epoch,'{}');
 perform pg_temp.check('Permission epoch revocation checked before idempotent replay',v.outcome='forbidden');
 perform pg_temp.check('No source raw canary in command audit',(select not coalesce(bool_or(changes::text like '%never_send%' or changes::text like '%cipher%'),false) from public.audit_logs where organization_id=o and action like 'webhook.%'));
end $$;

